import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Performance Profiler","description":"","frontmatter":{},"headers":[],"relativePath":"features/profiler.md","filePath":"features/profiler.md"}'),n={name:"features/profiler.md"};function l(r,a,p,o,h,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="performance-profiler" tabindex="-1">Performance Profiler <a class="header-anchor" href="#performance-profiler" aria-label="Permalink to &quot;Performance Profiler&quot;">​</a></h1><blockquote><p><strong><code>aeroci profile</code></strong> — Features 11–20</p></blockquote><p>The Profiler automatically records every run, measures per-step timing, tracks memory usage, estimates costs, and detects performance trends.</p><hr><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aeroci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # profiler runs automatically</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">aeroci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> profile</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # view run history and trends</span></span></code></pre></div><hr><h2 id="feature-11-—-per-step-timing-table" tabindex="-1">Feature 11 — Per-Step Timing Table <a class="header-anchor" href="#feature-11-—-per-step-timing-table" aria-label="Permalink to &quot;Feature 11 — Per-Step Timing Table&quot;">​</a></h2><p>After every <code>aeroci run</code>, a timing table is printed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>⏱  Per-Step Timing Breakdown</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│     Job           Step                    Duration   Relative              │</span></span>
<span class="line"><span>├────────────────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ ✔   build         Checkout                1ms        ░░░░░░░░░░░░░░░░░░░░  │</span></span>
<span class="line"><span>│ ✔   build         Setup Node.js           1ms        ░░░░░░░░░░░░░░░░░░░░  │</span></span>
<span class="line"><span>│ ✔   build         Install dependencies    3241ms     ████████████████████  │</span></span>
<span class="line"><span>│ ✔   build         Run tests               892ms      ████████░░░░░░░░░░░░  │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>The <code>Relative</code> column shows a mini bar chart proportional to each step&#39;s share of the total runtime.</p><hr><h2 id="feature-12-—-slowest-step-highlighter" tabindex="-1">Feature 12 — Slowest Step Highlighter <a class="header-anchor" href="#feature-12-—-slowest-step-highlighter" aria-label="Permalink to &quot;Feature 12 — Slowest Step Highlighter&quot;">​</a></h2><p>The slowest step is always highlighted at the bottom of the timing report:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Slowest step: &quot;Install dependencies&quot; in job build (3241ms)</span></span></code></pre></div><hr><h2 id="feature-13-—-ci-cost-estimator" tabindex="-1">Feature 13 — CI Cost Estimator <a class="header-anchor" href="#feature-13-—-ci-cost-estimator" aria-label="Permalink to &quot;Feature 13 — CI Cost Estimator&quot;">​</a></h2><p>Calculates how much money and time AeroCI saved vs running on GitHub Actions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>💰 CI Cost &amp; Time Savings</span></span>
<span class="line"><span>  • Local Execution Time     : 4.14s</span></span>
<span class="line"><span>  • Est. GitHub Actions Time : 34.14s (incl. runner setup)</span></span>
<span class="line"><span>  • Time Saved               : 30.00s  (8.2x faster)</span></span>
<span class="line"><span>  • Est. Billable Minutes    : 0.57 min</span></span>
<span class="line"><span>  • Est. Cost Saved          : $0.0046 USD</span></span></code></pre></div><p>Calculations use GitHub&#39;s public <a href="https://docs.github.com/en/billing/managing-billing-for-github-actions/about-billing-for-github-actions" target="_blank" rel="noreferrer">billing rates</a>:</p><ul><li><strong>Linux:</strong> $0.008 / minute</li><li><strong>macOS:</strong> $0.08 / minute</li><li><strong>Windows:</strong> $0.016 / minute</li></ul><hr><h2 id="feature-14-—-run-history-logger" tabindex="-1">Feature 14 — Run History Logger <a class="header-anchor" href="#feature-14-—-run-history-logger" aria-label="Permalink to &quot;Feature 14 — Run History Logger&quot;">​</a></h2><p>Every run is appended to <code>.aeroci-artifacts/history.jsonl</code> (newline-delimited JSON):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-08-12T04:34:18.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;workflow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;totalMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4142</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;passed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;peakMemMB&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-08-12T04:36:22.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;workflow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;totalMs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3891</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;passed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;peakMemMB&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>View with: <code>aeroci profile</code></p><hr><h2 id="feature-15-—-trend-analyzer" tabindex="-1">Feature 15 — Trend Analyzer <a class="header-anchor" href="#feature-15-—-trend-analyzer" aria-label="Permalink to &quot;Feature 15 — Trend Analyzer&quot;">​</a></h2><p>When 2+ historical runs exist, the profiler compares the latest run to the average:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>📈 Performance Trend (vs last 5 runs)</span></span>
<span class="line"><span>  • Average Duration: 4.02s</span></span>
<span class="line"><span>  • This Run:         4.14s  (+3.0% slower)</span></span>
<span class="line"><span>  • Trend:            ↗ Slightly slower</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Sparkline: ▂▃▂▃▄▃▃▄  (last 8 runs)</span></span></code></pre></div><hr><h2 id="feature-16-—-parallelism-analyzer" tabindex="-1">Feature 16 — Parallelism Analyzer <a class="header-anchor" href="#feature-16-—-parallelism-analyzer" aria-label="Permalink to &quot;Feature 16 — Parallelism Analyzer&quot;">​</a></h2><p>Detects jobs that <strong>could</strong> run in parallel (no <code>needs:</code> dependency between them) but are currently sequential:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>💡 Parallelism Opportunity</span></span>
<span class="line"><span>  Jobs &quot;lint&quot; and &quot;test&quot; have no dependency relationship.</span></span>
<span class="line"><span>  Consider running them in parallel to save ~45s.</span></span></code></pre></div><hr><h2 id="feature-17-—-cache-hit-simulator" tabindex="-1">Feature 17 — Cache Hit Simulator <a class="header-anchor" href="#feature-17-—-cache-hit-simulator" aria-label="Permalink to &quot;Feature 17 — Cache Hit Simulator&quot;">​</a></h2><p>Simulates <code>actions/cache</code> hit/miss logic using a local <code>.aeroci-artifacts/action-cache/index.json</code>:</p><ul><li><strong>First run:</strong> MISS — registers cache key for next run</li><li><strong>Subsequent runs:</strong> HIT — simulates restored cache</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✔ [actions/cache]: Cache HIT for key &quot;node-modules-abc123&quot;</span></span>
<span class="line"><span>↩ Restored &quot;node_modules&quot; from local cache store</span></span></code></pre></div><hr><h2 id="feature-18-—-network-i-o-estimator" tabindex="-1">Feature 18 — Network I/O Estimator <a class="header-anchor" href="#feature-18-—-network-i-o-estimator" aria-label="Permalink to &quot;Feature 18 — Network I/O Estimator&quot;">​</a></h2><p>Estimates the amount of data that would be downloaded during a real CI run, based on detected operations:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Estimated Size</th></tr></thead><tbody><tr><td><code>npm install</code> (no lock)</td><td>~50 MB</td></tr><tr><td><code>npm ci</code> (with lock)</td><td>~30 MB</td></tr><tr><td><code>pip install -r requirements.txt</code></td><td>~20 MB</td></tr><tr><td><code>actions/checkout</code></td><td>~5 MB</td></tr><tr><td>Docker base image pull</td><td>~100 MB</td></tr></tbody></table><hr><h2 id="feature-19-—-memory-usage-tracker" tabindex="-1">Feature 19 — Memory Usage Tracker <a class="header-anchor" href="#feature-19-—-memory-usage-tracker" aria-label="Permalink to &quot;Feature 19 — Memory Usage Tracker&quot;">​</a></h2><p>Tracks Node.js heap usage during the simulation:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  • Peak Memory Used: 14 MB</span></span></code></pre></div><p>Reported in the run history for trend analysis.</p><hr><h2 id="feature-20-—-pipeline-efficiency-score" tabindex="-1">Feature 20 — Pipeline Efficiency Score <a class="header-anchor" href="#feature-20-—-pipeline-efficiency-score" aria-label="Permalink to &quot;Feature 20 — Pipeline Efficiency Score&quot;">​</a></h2><p>A 0–100 score evaluating your pipeline&#39;s configuration quality:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🏆 Pipeline Efficiency Score</span></span>
<span class="line"><span>  • Score: 87/100 🟢 Excellent</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Deductions:</span></span>
<span class="line"><span>    -5: No job timeout-minutes set</span></span>
<span class="line"><span>    -8: No caching step detected (npm install without cache)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Score</th><th>Rating</th></tr></thead><tbody><tr><td>90–100</td><td>🟢 Excellent</td></tr><tr><td>75–89</td><td>🟡 Good</td></tr><tr><td>50–74</td><td>🟠 Needs Work</td></tr><tr><td>0–49</td><td>🔴 Poor</td></tr></tbody></table><p><strong>Factors evaluated:</strong></p><ul><li>Job timeout configuration</li><li>Caching strategy</li><li>Step count per job</li><li>Use of matrix builds</li><li>Secrets management</li></ul>`,55)])])}const k=s(n,[["render",l]]);export{u as __pageData,k as default};
